[
	{
		"name": "",
		"text": "'Say, you look like a capable mage. I can sense a great ability for violence within you. Perhaps I can interest you in a job...?'",
		"options":
			[
				{
					"name": "The five families have fallen.",
                    "text": "'Your actions will bring a new dawn of justice to my people. I thank you.'",
					"action": [ { "deleteMapObject": -1 },
                    {"grantRewards": [
		      {"type": "item", "count": 1, "itemName": "Scroll of the Masters"},
                        {"type": "gold", "count": 500},
                        {"type": "card", "count": 1, "cardName": "Taigam, Master Opportunist"},
                        {"type": "card", "count": 1, "cardName": "Taigam, Ojutai Master"},
                        {"type": "card", "count": 1, "cardName": "Taigam, Sidisi's Hand"},
                        {"type": "card", "count": 1, "cardName": "Taigam's Scheming"}              
                      ] } ]
                    ,
					"condition": [{"item": "Abzan Gauntlet"}, {"item": "Jeskai Gauntlet"}, {"item": "Mardu Gauntlet"}, {"item": "Sultai Gauntlet"}, {"item": "Temur Gauntlet"}],
					"options": [ { "name": "(Continue)" } ]
				},
				{
					"name": "What kind of job?",
					"text": "'Quite simply, the khans of Tarkir's five clans have arrived on this blasted world, bereft of most of their defenses. I would like them all dead.'",
					"options": [ { "name": "What's in it for me?",
					"text": "'A chunk of gold and a powerful ancient scroll with the magical might of the ancient masters. Take the gauntlet from each khan's corpse and show me them for your reward.'",
					"options": [ { "name": "I'll see what I can do." } ]
					 }]
				},
                {
					"name": "I don't work for the world's sketchiest people.",
					"text": "'Begone, then. I have no use for those with an overdeveloped sense of morals.'",
					"options": [ { "name": "(Continue)" } ]
				}
			]
	}
]

